174	
175	    public class ProductDetailDto
176	    {
177	        public required string Id { get; set; }
178	        public required string Name { get; set; }
179	        public required string Description { get; set; }
180	        public required CategoryRefDto Category { get; set; }
181	        public required SubcategoryRefDto Subcategory { get; set; }
182	        public required IReadOnlyList<ProductPropertyDto> Properties { get; set; }
183	        public double? AverageRating { get; set; }
184	        public required int RatingCount { get; set; }
185	        public required IReadOnlyList<SupplierOfferDto> Offers { get; set; }
