    [Fact]
    public async Task GetProductsAsync_SortByIsCaseInsensitive()
    {
        SeedProductsWithOffers();

        var result = await _service.GetProductsAsync(1, subcategoryId: "SP1", sortBy: "PRICE", sortDirection: "asc");

