3	import { CatalogApiService } from '../catalog-api.service';
4	import { CategoryNav } from '../category-nav/category-nav';
5	import { CategorySummary, ProductSummary } from '../product.model';
6	import { PropertyFilters } from '../property-filters/property-filters';
7	import { SearchBox } from '../search-box/search-box';
8	import { SortSelect, SortSelection } from '../sort-select/sort-select';
9	
10	@Component({
11	  selector: 'app-product-list',
12	  imports: [CategoryNav, SortSelect, SearchBox, PropertyFilters],
13	  templateUrl: './product-list.html'
14	})
15	export class ProductList {
16	  private catalogApi = inject(CatalogApiService);
17	
18	  protected readonly page = signal(1);
19	  protected readonly items = signal<ProductSummary[]>([]);
20	  protected readonly totalCount = signal(0);
21	  protected readonly loading = signal(false);
22	  protected readonly pageSize = signal(0);
23	  protected readonly categories = signal<CategorySummary[]>([]);
24	  protected readonly selectedCategoryId = signal<string | null>(null);
25	  protected readonly selectedSubcategoryId = signal<string | null>(null);
26	  protected readonly selectedSortBy = signal<string | null>(null);
27	  protected readonly selectedSortDirection = signal<string | null>(null);
28	  protected readonly selectedSearch = signal<string | null>(null);
29	  protected readonly selectedPropertyFilters = signal<Record<string, string> | null>(null);
30	
31	  protected readonly selectedSubcategoryProperties = computed<string[]>(() => {
32	    const subcategoryId = this.selectedSubcategoryId();
33	    if (!subcategoryId) {
34	      return [];
35	    }
36	    for (const category of this.categories()) {
37	      const match = category.subcategories.find((s) => s.id === subcategoryId);
38	      if (match) {
39	        return match.properties;
40	      }
41	    }
42	    return [];
43	  });
44	
45	  protected readonly totalPages = computed(() => Math.max(1, Math.ceil(this.totalCount() / (this.pageSize() || 1))));
46	  protected readonly hasPreviousPage = computed(() => this.page() > 1);
47	  protected readonly hasNextPage = computed(() => this.page() * this.pageSize() < this.totalCount());
48	
49	  constructor() {
50	    this.loadPage(this.page());
51	    this.loadCategories();
52	  }
53	
54	  protected goToPreviousPage(): void {
55	    if (this.hasPreviousPage() && !this.loading()) {
56	      this.loadPage(this.page() - 1);
57	    }
58	  }
59	
60	  protected goToNextPage(): void {
61	    if (this.hasNextPage() && !this.loading()) {
62	      this.loadPage(this.page() + 1);
63	    }
64	  }
65	
66	  protected selectCategory(categoryId: string): void {
67	    if (this.loading()) {
68	      return;
69	    }
70	    this.selectedCategoryId.set(categoryId);
71	    this.selectedSubcategoryId.set(null);
72	    this.selectedPropertyFilters.set(null);
73	    this.loadPage(1);
74	  }
75	
76	  protected selectSubcategory(subcategoryId: string): void {
77	    if (this.loading()) {
78	      return;
79	    }
80	    this.selectedCategoryId.set(null);
81	    this.selectedSubcategoryId.set(subcategoryId);
82	    this.selectedPropertyFilters.set(null);
83	    this.loadPage(1);
84	  }
85	
86	  protected clearSelection(): void {
87	    if (this.loading()) {
88	      return;
89	    }
90	    this.selectedCategoryId.set(null);
91	    this.selectedSubcategoryId.set(null);
92	    this.selectedPropertyFilters.set(null);
93	    this.loadPage(1);
94	  }
95	
96	  protected onSortChanged(sort: SortSelection | null): void {
97	    if (this.loading()) {
98	      return;
99	    }
100	    this.selectedSortBy.set(sort?.sortBy ?? null);
101	    this.selectedSortDirection.set(sort?.sortDirection ?? null);
102	    this.loadPage(1);
103	  }
104	
105	  protected onSearchChanged(search: string | null): void {
106	    if (this.loading()) {
107	      return;
108	    }
109	    this.selectedSearch.set(search);
110	    this.loadPage(1);
