  it('renders the names of the returned items', () => {
    const fixture = TestBed.createComponent(ProductList);
    fixture.detectChanges();

    expectProductsRequest(httpMock, 1, {
      items: [
        { id: 'T01', name: 'Produkt Eins' },
        { id: 'T02', name: 'Produkt Zwei' }
