      page: 1,
      pageSize: 20,
      totalCount: 2
    });
    expectCategoriesRequest(httpMock);
    fixture.detectChanges();

    const text = (fixture.nativeElement as HTMLElement).textContent ?? '';
    expect(text).toContain('Produkt Eins');
    expect(text).toContain('Produkt Zwei');
